const esc = require("./index.js");
const cases = ["a-b", "-", "a-", "-a", "[]-x", "a.b", "[x]", "a+b", "a\\b", "How much $ for a unicorn?", "-[]-", "a-b-c"];
let bad = 0;
for (const v of cases) {
  const e = esc(v);
  for (const flags of ["", "u"]) {
    const m = new RegExp("^" + e + "$", flags).test(v);
    if (!m) { console.log("FAIL exact", JSON.stringify(v), "flags=" + JSON.stringify(flags), "->", JSON.stringify(e)); bad++; }
  }
  // embedded in the middle of a character class
  const cc = new RegExp("^[" + e + "$]$", "u");
  if (!(cc.test(v) && cc.test("$"))) { console.log("FAIL class", JSON.stringify(v), "->", JSON.stringify(e)); bad++; }
}
console.log("sample escapes:", JSON.stringify(esc("a-b")), JSON.stringify(esc("-")), JSON.stringify(esc("How much $ for a unicorn?")));
console.log("anchor rejection (u):", new RegExp("^" + esc("a-b") + "$", "u").test("axb") === false);
console.log(bad === 0 ? "ALL EXTRA CHECKS PASS" : bad + " EXTRA CHECKS FAILED");
'

